const spreadsheetId = $input.first().json.spreadsheetId;
const sheetName = $input.first().json.sheetName;

// Try to read the sheet
try {
  const response = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'GET',
      url: `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}/values/${encodeURIComponent(sheetName)}!A:Z`,
      json: true
    }
  );

  const rows = response.values || [];
  const urls = rows.slice(1) // Skip header row
    .map(row => row[0]) // Assume URL is first column
    .filter(Boolean)
    .filter(u => typeof u === 'string')
    .map(u => u.trim())
    .filter(u => u && u.toLowerCase() !== 'url');

  return [{ json: { existingUrls: urls } }];
} catch (error) {
  // Sheet is empty or doesn't exist yet
  console.log('No existing data:', error.message);
  return [{ json: { existingUrls: [] } }];
}

// Helper: decode HTML entities
function decodeEntities(text) {
  if (!text) return '';
  return text
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-fA-F]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ');
}

const articles = [];
const inputItems = $input.all();

for (let idx = 0; idx < inputItems.length; idx++) {
  const item = inputItems[idx];
  const html = item.json.html || '';
  const emailDate = item.json.date ? new Date(item.json.date) : new Date();

  if (!html) continue;

  // Split by the unique class to find articles
  const segments = html.split('class="gse_alrt_title"');

  for (let i = 1; i < segments.length; i++) {
    try {
      const before = segments[i - 1];
      const after = segments[i];

      // Extract href
      const hrefMatch = before.match(/href="([^"]+)"[^>]*$/);
      if (!hrefMatch) continue;

      // Extract title
      const titleMatch = after.match(/^[^>]*>([^<]+)<\/a>/);
      if (!titleMatch) continue;

      const url = hrefMatch[1];
      const title = decodeEntities(titleMatch[1].trim());

      // FIX #1: Skip non-article links
      if (title.toLowerCase().includes('aanbevelingen bekijken') ||
          title.toLowerCase().includes('view all recommendations') ||
          url.includes('/scholar_alerts') ||
          url.includes('scholar_url') === false && !url.includes('url=')) {
        continue;
      }

      // FIX #2: Extract authors and source with flexible dash splitting
      let authors = '';
      let source = '';
      let year = '';

      // Try multiple regex patterns for the author/source div
      const authorsMatch = after.match(/<div[^>]*(?:color:\s*#006621|class="[^"]*gse_alrt_sni_ausr[^"]*")[^>]*>(.*?)<\/div>/s)
                        || after.match(/<div[^>]*color:\s*#006621[^>]*>([^<]+)<\/div>/);
      if (authorsMatch) {
        // Remove any HTML tags inside the match
        const rawText = authorsMatch[1].replace(/<[^>]+>/g, '').trim();
        const authorSource = decodeEntities(rawText);

        // Split on various dash types: hyphen, en-dash, em-dash
        const parts = authorSource.split(/\s[-\u2013\u2014]\s/);
        if (parts.length >= 2) {
          authors = parts[0].trim();
          // Everything after the first dash is source info
          const sourceAndYear = parts.slice(1).join(' - ').trim();
          // Extract year (4-digit number at the end)
          const yearMatch = sourceAndYear.match(/,?\s*(\d{4})\s*$/);
          if (yearMatch) {
            year = yearMatch[1];
            source = sourceAndYear.replace(/,?\s*\d{4}\s*$/, '').trim();
          } else {
            source = sourceAndYear;
          }
        } else {
          authors = authorSource;
        }
      }

      // Extract summary (FIX #3: decode entities)
      let summary = '';
      const summaryMatch = after.match(/<div[^>]*class="gse_alrt_sni"[^>]*>([^<]+)/);
      if (summaryMatch) {
        summary = decodeEntities(summaryMatch[1].trim().replace(/\s+/g, ' '));
      }

      // Clean URL (extract real URL from scholar redirect)
      let cleanUrl = url;
      if (url.includes('scholar.google')) {
        const urlParam = url.match(/url=([^&]+)/);
        if (urlParam) {
          cleanUrl = decodeURIComponent(urlParam[1]);
        }
      }

      articles.push({
        title: title,
        url: cleanUrl.trim(),
        authors: authors,
        source: source,
        year: year,
        summary: summary,
        emailDate: emailDate.toISOString(),
        addedDate: new Date().toISOString()
      });
    } catch (err) {
      console.log(`Error parsing article ${i}:`, err.message);
    }
  }
}

console.log(`Extracted ${articles.length} articles`);
return articles.map(article => ({ json: article }));

const items = $input.all();
if (!items.length) return [];

const firstItem = items[0].json;
const existingUrls = firstItem.existingUrls || [];
const spreadsheetId = firstItem.spreadsheetId;
const sheetName = firstItem.sheetName;

const existing = new Set(existingUrls.filter(u => u && typeof u === 'string').map(u => u.toLowerCase()));
const output = [];

for (const item of items) {
  const url = (item.json.url || item.json.URL || '').toString().trim();
  if (!url) continue;
  if (existing.has(url.toLowerCase())) continue;

  output.push({ 
    json: {
      url: item.json.url,
      title: item.json.title,
      authors: item.json.authors,
      source: item.json.source,
      year: item.json.year || '',
      summary: item.json.summary,
      emailDate: item.json.emailDate,
      addedDate: item.json.addedDate,
      spreadsheetId: spreadsheetId,
      sheetName: sheetName
    }
  });
}

return output;

