// === SMART TITLE CASING ===
function toSentenceCase(title) {
  if (!title || title.length === 0) return title;

  const words = title.split(/\s+/);
  const alphaWords = words.filter(w => w.replace(/[^a-zA-Z]/g, '').length > 1);
  if (alphaWords.length === 0) return title;

  // Detect ALL CAPS
  const isAllCaps = alphaWords.every(w => {
    const clean = w.replace(/[^a-zA-Z]/g, '');
    return clean === clean.toUpperCase();
  });

  // Detect Title Case (most content words start uppercase)
  const smallWords = new Set(['a','an','the','and','but','or','for','nor','on','at','to','from','by','in','of','with','as','is','are','was','were','its','using','via']);
  const contentWords = alphaWords.filter(w => !smallWords.has(w.toLowerCase()) && w.replace(/[^a-zA-Z]/g, '').length > 2);
  const isTitleCase = !isAllCaps && contentWords.length > 2 &&
    contentWords.filter(w => /^[A-Z]/.test(w)).length / contentWords.length > 0.7;

  if (!isAllCaps && !isTitleCase) return title; // already sentence case

  // Acronyms to preserve (all uppercase)
  const acronyms = new Set(['AI','AIED','ICT','SAMR','TPACK','HINA','HEI','HEIs','STEM','MOOC','MOOCs','LMS','VR','AR','XR','IoT','API','OECD','UNESCO','GIS','NLP','ML','DL','GPT','LLM','LLMs','SEM','UTAUT','TAM','PCK','ER','IT','CALL','EFL','ESL','ELT','SLA','CLIL','EMI','SDG','SDGs','PISA','IRT','SRL','CSCL','TEL','OER','CBL','PBL','SPSS','USA','UK','EU','VLE','CMS','TESOL']);

  // Proper nouns (capitalize first letter)
  const properNouns = new Set(['english','spanish','french','german','dutch','chinese','vietnamese','arabic','portuguese','italian','japanese','korean','russian','turkish','indonesian','malay','hindi','moroccan','zambian','nigerian','indian','peruvian','austrian','malaysian','croatian','european','african','asian','american','latin','brazilian','mexican','czech','scandinavian','nordic','jordan','jordanian','vietnamese','vietnam','india','peru','austria','malaysia','morocco','croatia','zambia','nigeria','china','japan','korea','germany','spain','france','brazil','mexico','oman','singapore','moodle','google','edmodo','bloom','vygotsky','piaget','bandura','likert']);

  // Split by colon to capitalize first word of each segment
  const colonParts = title.split(':');

  const result = colonParts.map((part, partIdx) => {
    const trimmed = part.trim();
    if (!trimmed) return '';

    // Split preserving whitespace
    const tokens = trimmed.split(/(\s+)/);
    let wordIndex = 0;

    const processed = tokens.map(token => {
      if (/^\s+$/.test(token)) return token; // whitespace

      const currentWordIdx = wordIndex++;

      // Handle parenthetical acronyms like (AIED) or (HEIs)
      const parenMatch = token.match(/^\(([a-zA-Z]+)\)(.*)$/);
      if (parenMatch) {
        const inner = parenMatch[1].toUpperCase();
        if (inner.length >= 2 && inner.length <= 6) {
          return `(${inner})${parenMatch[2]}`;
        }
      }

      // Split word from trailing punctuation
      const match = token.match(/^([a-zA-Z][a-zA-Z'-]*)(.*)$/);
      if (!match) return token; // numbers, symbols

      let word = match[1];
      const trailing = match[2];

      // Handle hyphenated words
      if (word.includes('-')) {
        const parts = word.split('-');
        const processed = parts.map((p, pIdx) => {
          const upper = p.toUpperCase();
          if (acronyms.has(upper) && p.length <= 6) return upper;
          if (properNouns.has(p.toLowerCase())) return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
          if (currentWordIdx === 0 && pIdx === 0) return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
          return p.toLowerCase();
        });
        return processed.join('-') + trailing;
      }

      const upperWord = word.toUpperCase();

      // Check acronym (2-6 uppercase letters)
      if (acronyms.has(upperWord) && word.length >= 2 && word.length <= 6) {
        return upperWord + trailing;
      }

      // Check proper noun
      if (properNouns.has(word.toLowerCase())) {
        return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase() + trailing;
      }

      // First word of segment: capitalize
      if (currentWordIdx === 0) {
        return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase() + trailing;
      }

      // Everything else: lowercase
      return word.toLowerCase() + trailing;
    });

    return processed.join('');
  }).join(': ');

  return result;
}

// === ENRICHMENT ===
const items = $input.all();
const results = [];

function normalizeTitle(t) {
  return (t || '').toLowerCase().replace(/[^a-z0-9]/g, '').replace(/[li]/g, 'i');
}
function similarity(a, b) {
  if (!a || !b) return 0;
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1;
  let matches = 0;
  const compareLen = Math.min(a.length, b.length);
  for (let i = 0; i < compareLen; i++) { if (a[i] === b[i]) matches++; }
  return matches / maxLen;
}

for (const item of items) {
  const data = { ...item.json };

  const hasTruncation = 
    (data.authors && (data.authors.includes('...') || data.authors.includes('\u2026'))) ||
    (data.source && (data.source.includes('...') || data.source.includes('\u2026')));
  const missingData = !data.source || !data.year;
  const needsEnrich = (hasTruncation || missingData) && data.title;

  if (needsEnrich) {
    let bestWork = null;
    let enrichSource = '';

    // Strategy 1: OpenAlex title search
    try {
      const searchTitle = encodeURIComponent(data.title.substring(0, 200));
      const response = await this.helpers.httpRequest({ method: 'GET', url: `https://api.openalex.org/works?search=${searchTitle}&per_page=5&mailto=n8n-workflow@example.com`, json: true, timeout: 8000 });
      if (response.results && response.results.length > 0) {
        const ourTitle = normalizeTitle(data.title);
        for (const work of response.results) {
          if (similarity(ourTitle, normalizeTitle(work.title)) > 0.85) {
            bestWork = { authors: (work.authorships||[]).map(a => a.author?.display_name).filter(Boolean), source: work.primary_location?.source?.display_name || work.host_venue?.display_name || '', year: work.publication_year ? String(work.publication_year) : '' };
            enrichSource = 'openalex';
            break;
          }
        }
      }
    } catch (err) { console.log(`OpenAlex failed: ${err.message}`); }

    // Strategy 2: Crossref title search
    if (!bestWork) {
      try {
        const searchTitle = encodeURIComponent(data.title.substring(0, 200));
        const response = await this.helpers.httpRequest({ method: 'GET', url: `https://api.crossref.org/works?query.title=${searchTitle}&rows=3&mailto=n8n-workflow@example.com`, json: true, timeout: 10000 });
        if (response.message && response.message.items) {
          const ourTitle = normalizeTitle(data.title);
          for (const work of response.message.items) {
            if (similarity(ourTitle, normalizeTitle((work.title||[''])[0])) > 0.85) {
              bestWork = { authors: (work.author||[]).map(a => [a.given,a.family].filter(Boolean).join(' ')).filter(Boolean), source: (work['container-title']||[''])[0]||'', year: work.published?.['date-parts']?.[0]?.[0] ? String(work.published['date-parts'][0][0]) : '' };
              enrichSource = 'crossref';
              break;
            }
          }
        }
      } catch (err) { console.log(`Crossref failed: ${err.message}`); }
      await new Promise(r => setTimeout(r, 200));
    }

    // Strategy 3: DOI from URL
    if (!bestWork && data.url) {
      const doiMatch = data.url.match(/\/(10\.[^/]+\/[^\s?&#]+)/);
      if (doiMatch) {
        try { const r = await this.helpers.httpRequest({ method:'GET', url:`https://api.openalex.org/works/doi:${doiMatch[1]}?mailto=n8n-workflow@example.com`, json:true, timeout:8000 }); if(r?.title) { bestWork = { authors:(r.authorships||[]).map(a=>a.author?.display_name).filter(Boolean), source:r.primary_location?.source?.display_name||'', year:r.publication_year?String(r.publication_year):'' }; enrichSource='openalex-doi'; } } catch(e){}
        if (!bestWork) { try { const r = await this.helpers.httpRequest({ method:'GET', url:`https://api.crossref.org/works/${doiMatch[1]}`, json:true, timeout:8000 }); if(r.message?.title) { const w=r.message; bestWork = { authors:(w.author||[]).map(a=>[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean), source:(w['container-title']||[''])[0]||'', year:w.published?.['date-parts']?.[0]?.[0]?String(w.published['date-parts'][0][0]):'' }; enrichSource='crossref-doi'; } } catch(e){} }
      }
    }

    // Strategy 4: Frontiers year from URL
    if (!bestWork && data.url && data.url.includes('frontiersin.org')) {
      const yearMatch = data.url.match(/feduc\.(\d{4})/);
      if (yearMatch && !data.year) data.year = yearMatch[1];
    }

    if (bestWork) {
      console.log(`Enriched "${data.title.substring(0, 50)}..." via ${enrichSource}`);
      if (bestWork.authors?.length > 0 && (hasTruncation || bestWork.authors.length > (data.authors||'').split(',').length)) data.authors = bestWork.authors.join(', ');
      if (!data.source && bestWork.source) data.source = bestWork.source;
      if (data.source && (data.source.includes('...')||data.source.includes('\u2026')) && bestWork.source) data.source = bestWork.source;
      if (!data.year && bestWork.year) data.year = bestWork.year;
    }
    await new Promise(r => setTimeout(r, 200));
  }

  // Apply smart title casing
  if (data.title) {
    data.title = toSentenceCase(data.title);
  }

  results.push({ json: data });
}

console.log(`Processed ${results.length} articles`);
return results;
